import { createFileRoute } from "@tanstack/react-router";
import { Archive, ArrowLeft, Bell, CheckCircle2, ChevronRight, ClipboardCheck, Factory, FileText, History, LayoutDashboard, Menu, PackageSearch, Plus, Search, Settings2, ShieldCheck, UsersRound, Wrench, X } from "lucide-react";
import { useEffect, useMemo, useState, type FormEvent, type ReactNode } from "react";

type AreaId = "home" | "rnd" | "stores" | "production" | "quality" | "sales" | "people";
type RecordStatus = "Draft" | "Open" | "In review" | "Approved" | "Released" | "Archived";
type Priority = "Low" | "Normal" | "High" | "Critical";
type RecordItem = { id: string; area: AreaId; type: string; title: string; status: RecordStatus; priority: Priority; reference: string; createdAt: string; updatedAt: string; notes: string; fields: Record<string, string>; archived?: boolean };
type Department = { id: string; name: string; code: string; departmentType: string; customType?: string; active: boolean; lead: string; sortOrder: number; settings: DepartmentSettings };
type DepartmentSettings = { activityTypes: string[]; statuses: string[]; priorities: string[]; templates: string[]; approvalGates: string[]; milestones: string[]; kpis: string[]; calendar: string; notifications: string[]; prefix: string; sequence: number; format: string };
type DepartmentRole = { id: string; departmentId: string; name: string; permissions: string[]; active: boolean };
type AuditEvent = { id: string; at: string; action: string; detail: string };
type MasterData = { people: string[]; suppliers: string[]; parts: string[]; products: string[]; customers: string[]; locations: string[]; routes: string[]; documentTypes: string[] };
type SetupState = { company: string; location: string; workingDays: string; timezone: string; numbering: string };
type PortalState = { setup: SetupState; setupStep: number; records: RecordItem[]; masters: MasterData; departments: Department[]; roles: DepartmentRole[]; approvals: { id: string; title: string; recordId: string; outcome: "Pending" | "Approved" | "Rejected" | "Returned"; updatedAt: string }[]; documents: { id: string; title: string; url: string; type: string }[]; audit: AuditEvent[]; notifications: string[] };

const areas = [
  { id: "home" as const, name: "Home / Command Center", short: "Home", icon: LayoutDashboard, recordType: "Task", summary: "Today, priority, approvals and progress" },
  { id: "rnd" as const, name: "R&D & Projects", short: "R&D", icon: Wrench, recordType: "Project", summary: "Projects, BOMs, prototype work and design gates" },
  { id: "stores" as const, name: "Purchasing & Stores", short: "Stores", icon: PackageSearch, recordType: "Purchase request", summary: "Requests, purchase orders and stock movement" },
  { id: "production" as const, name: "Production", short: "Production", icon: Factory, recordType: "Production order", summary: "Work orders, testing, release and traceability" },
  { id: "quality" as const, name: "Quality", short: "Quality", icon: ShieldCheck, recordType: "Inspection", summary: "Inspections, NCRs, CAPAs and actions" },
  { id: "sales" as const, name: "Sales & Customers", short: "Sales", icon: UsersRound, recordType: "Enquiry", summary: "Enquiries, requirements, orders and client updates" },
  { id: "people" as const, name: "People & Administration", short: "Admin", icon: Settings2, recordType: "Person", summary: "People, access, assets, policies and portal setup" },
];
const departmentTypes = ["R&D/Engineering", "Purchasing/Stores", "Production/Manufacturing", "Quality", "Sales/Customer Success", "People/HR", "Administration", "Operations", "Finance", "IT/Support", "Other/custom"];
const permissionOptions = ["records:view", "records:create", "records:edit", "tasks:assign", "approvals:routine", "documents:manage", "settings:manage"];
const setupSteps = ["Company, locations & document numbers", "Departments & department leads", "Team members, roles & access", "Project stages & approval gates", "Parts, storage & suppliers", "Customers, pipeline & sharing rules", "Production routes & release rules", "Document naming & responsibility", "Notifications & escalation rules", "Training & go-live checklist"];
const storeKey = "six-sense-portal-v3";
const blankSettings = (): DepartmentSettings => ({ activityTypes: [], statuses: ["Draft", "Open", "In review", "Approved", "Released"], priorities: ["Low", "Normal", "High", "Critical"], templates: [], approvalGates: [], milestones: [], kpis: [], calendar: "Monday – Saturday", notifications: [], prefix: "", sequence: 1, format: "{PREFIX}-{YYYY}-{####}" });
const emptyPortal = (): PortalState => ({ setup: { company: "Six Sense Mobility", location: "Noida", workingDays: "Monday – Saturday", timezone: "Asia/Kolkata", numbering: "SSM-{AREA}-{YYYY}-{####}" }, setupStep: 0, records: [], masters: { people: [], suppliers: [], parts: [], products: [], customers: [], locations: ["Noida"], routes: [], documentTypes: [] }, departments: [], roles: [], approvals: [], documents: [], audit: [], notifications: [] });
const createId = () => crypto.randomUUID();
const now = () => new Date().toLocaleString("en-IN", { dateStyle: "medium", timeStyle: "short" });
const areaById = (id: AreaId) => areas.find((area) => area.id === id) ?? areas[0];
const areaDepartmentType: Partial<Record<AreaId, string>> = { rnd: "R&D/Engineering", stores: "Purchasing/Stores", production: "Production/Manufacturing", quality: "Quality", sales: "Sales/Customer Success", people: "People/HR" };
const readPortal = (): PortalState => { const base = emptyPortal(); try { const raw = window.localStorage.getItem(storeKey) ?? window.localStorage.getItem("six-sense-portal-v2"); if (!raw) return base; const value = JSON.parse(raw) as Partial<PortalState>; return { ...base, ...value, setup: { ...base.setup, ...value.setup }, masters: { ...base.masters, ...value.masters }, departments: Array.isArray(value.departments) ? value.departments.map((department) => ({ ...department, settings: { ...blankSettings(), ...department.settings } })) : [], roles: Array.isArray(value.roles) ? value.roles : [], records: Array.isArray(value.records) ? value.records : [], approvals: Array.isArray(value.approvals) ? value.approvals : [], documents: Array.isArray(value.documents) ? value.documents : [], audit: Array.isArray(value.audit) ? value.audit : [], notifications: Array.isArray(value.notifications) ? value.notifications : [] }; } catch { return base; } };

export const Route = createFileRoute("/")({ head: () => ({ meta: [{ title: "Command Center — Six Sense Mobility" }, { name: "description", content: "Operational workspace for Six Sense Mobility in Noida." }, { property: "og:title", content: "Command Center — Six Sense Mobility" }, { property: "og:description", content: "Operational workspace and setup hub for Six Sense Mobility." }, { property: "og:type", content: "website" }, { name: "twitter:card", content: "summary_large_image" }] }), component: Portal });

function Portal() {
  const [portal, setPortal] = useState<PortalState | null>(null); const [activeArea, setActiveArea] = useState<AreaId>("home"); const [selectedId, setSelectedId] = useState<string | null>(null); const [view, setView] = useState<"queue" | "detail" | "summary">("queue"); const [modal, setModal] = useState<"create" | "wizard" | "search" | "approvals" | "documents" | "history" | "admin" | null>(null); const [mobileMenu, setMobileMenu] = useState(false); const [notice, setNotice] = useState<string | null>(null); const [departmentContext, setDepartmentContext] = useState<string | null>(null);
  useEffect(() => setPortal(readPortal()), []); useEffect(() => { if (portal) window.localStorage.setItem(storeKey, JSON.stringify(portal)); }, [portal]);
  if (!portal) return <main className="grid min-h-screen place-items-center bg-background text-muted-foreground">Opening your portal…</main>;
  const update = (recipe: (state: PortalState) => PortalState) => setPortal((state) => state ? recipe(state) : state);
  const log = (action: string, detail: string) => update((state) => ({ ...state, audit: [{ id: createId(), at: now(), action, detail }, ...state.audit].slice(0, 100), notifications: [detail, ...state.notifications].slice(0, 100) }));
  const announce = (message: string) => { setNotice(message); window.setTimeout(() => setNotice(null), 3500); };
  const navigate = (area: AreaId) => { setActiveArea(area); setView("queue"); setSelectedId(null); setMobileMenu(false); };
  const addRecord = (input: Omit<RecordItem, "id" | "reference" | "createdAt" | "updatedAt">) => { const count = portal.records.filter((record) => record.area === input.area).length + 1; const prefix = areaById(input.area).short.toUpperCase().replace(/[^A-Z]/g, "").slice(0, 5); const record: RecordItem = { ...input, id: createId(), reference: input.fields["controlledNumber"] || `${prefix}-${String(count).padStart(4, "0")}`, createdAt: now(), updatedAt: now() }; update((state) => ({ ...state, records: [record, ...state.records] })); log("Record created", `${record.reference} created`); setSelectedId(record.id); setView("detail"); setModal(null); announce(`${record.reference} created.`); };
  const activeRecords = portal.records.filter((record) => !record.archived); const selected = activeRecords.find((record) => record.id === selectedId); const active = areaById(activeArea);
  return <main className="min-h-screen bg-background text-foreground"><aside className="fixed inset-y-0 left-0 z-30 hidden w-72 border-r border-border bg-sidebar p-4 lg:flex lg:flex-col"><Brand/><nav className="mt-8 space-y-1" aria-label="Primary navigation">{areas.map((area) => <AreaNav key={area.id} area={area} active={activeArea === area.id} onClick={() => navigate(area.id)}/>)}</nav><button onClick={() => setModal("wizard")} className="mt-auto flex w-full items-center gap-3 border-t border-sidebar-border pt-4 text-left text-sm font-semibold"><Settings2 className="size-4"/>Portal setup <span className="ml-auto font-mono text-[10px]">{portal.setupStep + 1}/10</span></button></aside><section className="min-h-screen lg:pl-72"><header className="sticky top-0 z-20 border-b border-border bg-background/95 backdrop-blur"><div className="flex h-16 items-center gap-3 px-4 md:px-8"><button aria-label="Open menu" onClick={() => setMobileMenu(true)} className="grid size-10 place-items-center border border-border bg-panel lg:hidden"><Menu className="size-4"/></button><button onClick={() => navigate("home")} className="min-w-0 flex-1 text-left"><p className="truncate text-sm font-semibold md:text-base">{active.name}</p><p className="font-mono text-[10px] uppercase tracking-[0.14em] text-muted-foreground">{departmentContext ? `${portal.departments.find((item) => item.id === departmentContext)?.name ?? "Department"} · Administrator context` : `All departments · ${portal.setup.location}`}</p></button><HeaderAction label="Search" icon={Search} onClick={() => setModal("search")}/><HeaderAction label="Administration" icon={Settings2} onClick={() => setModal("admin")}/><HeaderAction label="History" icon={Bell} onClick={() => setModal("history")}/></div></header><div className="mx-auto max-w-7xl px-4 pb-28 pt-6 md:px-8 md:pt-8 lg:pb-10">{activeArea === "home" ? <CommandCenter portal={portal} onCreate={() => setModal("create")} onNavigate={navigate} onAdmin={() => setModal("admin")} onSetup={() => setModal("wizard")}/> : view === "detail" && selected ? <RecordDetail record={selected} onBack={() => setView("queue")} onSave={(patch) => { update((state) => ({ ...state, records: state.records.map((record) => record.id === selected.id ? { ...record, ...patch, updatedAt: now() } : record) })); log("Record updated", `${selected.reference} updated`); }} onArchive={() => { update((state) => ({ ...state, records: state.records.map((record) => record.id === selected.id ? { ...record, archived: true, status: "Archived", updatedAt: now() } : record) })); log("Record archived", `${selected.reference} archived`); setView("queue"); }} /> : <DepartmentWorkspace area={active} records={activeRecords.filter((record) => record.area === activeArea)} department={portal.departments.find((item) => item.id === departmentContext) ?? findAreaDepartment(portal.departments, activeArea)} contextName={departmentContext ? "Administrator" : "Workspace"} view={view} onView={setView} onCreate={() => setModal("create")} onSelect={(id) => { setSelectedId(id); setView("detail"); }} onAdmin={() => setModal("admin")} />}</div></section><nav className="fixed inset-x-0 bottom-0 z-30 grid grid-cols-5 border-t border-border bg-background/95 px-1 pb-[max(.5rem,env(safe-area-inset-bottom))] pt-1 backdrop-blur lg:hidden">{areas.slice(0, 4).map((area) => <button key={area.id} onClick={() => navigate(area.id)} className={`flex min-h-14 flex-col items-center justify-center gap-1 text-[10px] ${activeArea === area.id ? "bg-accent text-accent-foreground" : "text-muted-foreground"}`}><area.icon className="size-4"/><span>{area.short}</span></button>)}<button onClick={() => setMobileMenu(true)} className="flex min-h-14 flex-col items-center justify-center gap-1 text-[10px] text-muted-foreground"><Menu className="size-4"/><span>More</span></button></nav>{mobileMenu && <MobileMenu onClose={() => setMobileMenu(false)} onNavigate={navigate}/>} {modal === "create" && <RecordForm area={activeArea} portal={portal} onClose={() => setModal(null)} onSave={addRecord}/>} {modal === "wizard" && <Wizard portal={portal} onClose={() => setModal(null)} onSave={(next) => { setPortal(next); log("Setup saved", "Portal setup progress saved"); }}/>} {modal === "search" && <SearchPanel records={activeRecords} onClose={() => setModal(null)} onSelect={(record) => { navigate(record.area); setSelectedId(record.id); setView("detail"); setModal(null); }}/>} {modal === "history" && <HistoryPanel audit={portal.audit} onClose={() => setModal(null)}/>} {modal === "approvals" && <ApprovalsPanel approvals={portal.approvals} onClose={() => setModal(null)}/>} {modal === "documents" && <DocumentsPanel documents={portal.documents} onClose={() => setModal(null)}/>} {modal === "admin" && <AdminCommandCenter portal={portal} activeDepartmentId={departmentContext} onClose={() => setModal(null)} onUpdate={update} onLog={log} onContext={(id) => { setDepartmentContext(id); setModal(null); navigate(id ? areaForDepartment(portal.departments.find((item) => item.id === id)) : "home"); }}/>} {notice && <div role="status" className="fixed bottom-20 left-4 right-4 z-[60] border border-border bg-ink px-4 py-3 text-sm text-primary-foreground shadow-lg lg:bottom-6 lg:left-auto lg:right-6 lg:w-96">{notice}</div>}</main>;
}

function findAreaDepartment(departments: Department[], area: AreaId) { const type = areaDepartmentType[area]; return departments.find((department) => department.active && department.departmentType === type); }
function areaForDepartment(department: Department | undefined): AreaId { const map: Record<string, AreaId> = { "R&D/Engineering": "rnd", "Purchasing/Stores": "stores", "Production/Manufacturing": "production", Quality: "quality", "Sales/Customer Success": "sales", "People/HR": "people" }; return department ? map[department.departmentType] ?? "people" : "home"; }

function CommandCenter({ portal, onCreate, onNavigate, onAdmin, onSetup }: { portal: PortalState; onCreate: () => void; onNavigate: (area: AreaId) => void; onAdmin: () => void; onSetup: () => void }) { const records = portal.records.filter((record) => !record.archived); const pending = portal.approvals.filter((item) => item.outcome === "Pending").length; return <><PageHeader eyebrow="Operational workspace" title="Command center" description="Live operational totals appear only from records your team creates." actions={<><Action onClick={onSetup} label="Continue setup"/><Action onClick={onCreate} label="Create Task" primary/></>}/><section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Today" value={String(records.filter((record) => record.fields["dueDate"] === new Date().toISOString().slice(0, 10)).length)} detail="Due today" tone="steel"/><Metric label="Priority" value={String(records.filter((record) => record.priority === "High" || record.priority === "Critical").length)} detail="High or critical" tone="danger"/><Metric label="Pending" value={String(records.filter((record) => record.status === "Draft" || record.status === "Open").length)} detail="Open records" tone="warning"/><Metric label="Approvals" value={String(pending)} detail="Human decisions" tone="moss"/></section><section className="mt-6 grid gap-5 xl:grid-cols-[minmax(0,1fr)_21rem]"><div className="border border-border bg-card"><div className="border-b border-border p-4"><p className="font-semibold">Department progress</p><p className="text-xs text-muted-foreground">Calculated from live record stages and statuses.</p></div><div>{areas.filter((area) => area.id !== "home").map((area) => { const areaRecords = records.filter((record) => record.area === area.id); const complete = areaRecords.filter((record) => record.status === "Approved" || record.status === "Released").length; const percent = areaRecords.length ? Math.round((complete / areaRecords.length) * 100) : 0; return <button key={area.id} onClick={() => onNavigate(area.id)} className="grid w-full grid-cols-[minmax(7rem,1fr)_3rem] items-center gap-4 border-b border-border px-4 py-4 text-left last:border-0"><span><span className="block text-sm font-medium">{area.name}</span><span className="text-xs text-muted-foreground">{areaRecords.length} records · {complete} completed</span></span><span className="font-mono text-xs text-steel">{percent}%</span></button>; })}</div></div><aside className="border border-border bg-panel p-4"><p className="font-semibold">Quick actions</p><div className="mt-3 grid gap-2"><Action onClick={onCreate} label="Create task"/><Action onClick={() => onNavigate("quality")} label="Review quality queue"/><Action onClick={onAdmin} label="Open administration"/></div><p className="mt-6 border-t border-border pt-4 text-xs leading-5 text-muted-foreground">Protected quality releases and financial decisions always require a recorded human approval.</p></aside></section></>; }

function DepartmentWorkspace({ area, records, department, contextName, view, onView, onCreate, onSelect, onAdmin }: { area: typeof areas[number]; records: RecordItem[]; department: Department | undefined; contextName: string; view: "queue" | "summary"; onView: (view: "queue" | "summary") => void; onCreate: () => void; onSelect: (id: string) => void; onAdmin: () => void }) { const today = new Date().toISOString().slice(0, 10); const open = records.filter((record) => record.status === "Draft" || record.status === "Open"); const blocked = records.filter((record) => record.fields["blocker"]); const upcoming = records.filter((record) => record.fields["targetDate"] && record.fields["targetDate"] >= today).sort((a, b) => a.fields["targetDate"].localeCompare(b.fields["targetDate"])).slice(0, 3); return <><PageHeader eyebrow={`${area.short} · ${contextName}${department ? ` · ${department.name}` : " · no department configured"}`} title={area.name} description={area.summary} actions={<><Action onClick={() => onView(view === "queue" ? "summary" : "queue")} label={view === "queue" ? "Summary" : "Queue"}/><Action onClick={onCreate} label={`Create ${area.recordType}`} primary/></>}/><section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><Metric label="Today" value={String(records.filter((record) => record.fields["dueDate"] === today || record.fields["targetDate"] === today).length)} detail="Due today" tone="steel"/><Metric label="Priority" value={String(records.filter((record) => record.priority === "High" || record.priority === "Critical").length)} detail="Needs attention" tone="danger"/><Metric label="Pending" value={String(open.length)} detail="Draft or open" tone="warning"/><Metric label="Approvals" value="0" detail="No department approvals" tone="moss"/><Metric label="Progress" value={`${records.length ? Math.round(records.filter((record) => ["Approved", "Released"].includes(record.status)).length / records.length * 100) : 0}%`} detail="Completed" tone="steel"/></section><section className="mt-6 grid gap-5 xl:grid-cols-[minmax(0,1fr)_20rem]"><div className="border border-border bg-card">{view === "summary" ? <AreaSummary records={records}/> : records.length ? <div>{records.map((record) => <button key={record.id} onClick={() => onSelect(record.id)} className="grid w-full gap-3 border-b border-border px-4 py-4 text-left last:border-0 md:grid-cols-[8rem_minmax(0,1fr)_7rem_6rem]"><span className="font-mono text-xs text-muted-foreground">{record.reference}</span><span><strong className="block">{record.title}</strong><small className="mt-1 block text-muted-foreground">{record.type} · {record.updatedAt}</small></span><Status status={record.status}/><span className="font-mono text-[10px] uppercase text-muted-foreground">{record.priority}</span></button>)}</div> : <Empty onCreate={onCreate} label={`Create ${area.recordType}`}/>}</div><aside className="border border-border bg-panel p-4"><p className="font-semibold">Lead view</p><dl className="mt-4 space-y-3 text-sm"><div><dt className="font-mono text-[10px] uppercase text-muted-foreground">Overdue / blockers</dt><dd className="mt-1">{blocked.length} blocked record{blocked.length === 1 ? "" : "s"}</dd></div><div><dt className="font-mono text-[10px] uppercase text-muted-foreground">Upcoming milestones</dt><dd className="mt-1">{upcoming.length ? upcoming.map((record) => <p key={record.id}>{record.title}</p>) : "No upcoming milestones."}</dd></div></dl><Action onClick={onAdmin} label="Department settings"/></aside></section></>; }

function AreaSummary({ records }: { records: RecordItem[] }) { const statuses: RecordStatus[] = ["Draft", "Open", "In review", "Approved", "Released"]; return <div className="grid gap-3 p-4 sm:grid-cols-2 xl:grid-cols-5">{statuses.map((status) => <Metric key={status} label={status} value={String(records.filter((record) => record.status === status).length)} detail="Records" tone={status === "Open" ? "steel" : status === "Approved" || status === "Released" ? "moss" : "warning"}/>)}</div>; }

function RecordDetail({ record, onBack, onSave, onArchive }: { record: RecordItem; onBack: () => void; onSave: (patch: Partial<RecordItem>) => void; onArchive: () => void }) { const [editing, setEditing] = useState(false); const [title, setTitle] = useState(record.title); const [notes, setNotes] = useState(record.notes); const [status, setStatus] = useState<RecordStatus>(record.status); return <><button onClick={onBack} className="mb-5 inline-flex items-center gap-2 text-sm font-semibold text-steel"><ArrowLeft className="size-4"/>Back to queue</button><section className="border border-border bg-card"><div className="flex flex-wrap items-start justify-between gap-4 border-b border-border p-5"><div><p className="font-mono text-xs text-muted-foreground">{record.reference} · {record.type}</p><h1 className="mt-2 text-3xl font-semibold">{record.title}</h1></div><div className="flex gap-2"><Action onClick={() => setEditing(!editing)} label={editing ? "Cancel" : "Edit"}/><Action onClick={onArchive} label="Archive"/></div></div><div className="grid gap-6 p-5 md:grid-cols-[minmax(0,1fr)_15rem]">{editing ? <form onSubmit={(event) => { event.preventDefault(); if (title.trim()) { onSave({ title: title.trim(), notes, status }); setEditing(false); } }} className="space-y-4"><TextField label="Title" value={title} onChange={setTitle} required/><SelectField label="Status" value={status} options={["Draft", "Open", "In review", "Approved", "Released"]} onChange={(value) => setStatus(value as RecordStatus)}/><label className="block text-sm font-medium">Notes<textarea value={notes} onChange={(event) => setNotes(event.target.value.slice(0, 2000))} className="mt-1.5 min-h-28 w-full border border-input bg-background p-3 text-sm"/></label><Action label="Save changes" primary submit/></form> : <div><h2 className="font-semibold">Controlled fields</h2><dl className="mt-3 grid gap-3 sm:grid-cols-2">{Object.entries(record.fields).filter(([, value]) => value).map(([key, value]) => <div key={key} className="border-b border-border pb-2"><dt className="font-mono text-[10px] uppercase text-muted-foreground">{key.replace(/([A-Z])/g, " $1")}</dt><dd className="mt-1 text-sm">{value}</dd></div>)}</dl><h2 className="mt-6 font-semibold">Requirements / scope</h2><p className="mt-2 whitespace-pre-wrap text-sm leading-6 text-muted-foreground">{record.notes || "No scope added."}</p></div>}<aside className="border-l border-border pl-5"><Status status={record.status}/><p className="mt-6 font-mono text-[10px] uppercase text-muted-foreground">Priority</p><p className="mt-1 font-semibold">{record.priority}</p><p className="mt-6 text-xs text-muted-foreground">Created {record.createdAt}<br/>Updated {record.updatedAt}</p></aside></div></section></>; }

const formSpecs: Record<AreaId, { types: string[]; fields: { key: string; label: string; required?: boolean; kind?: "text" | "date" | "select"; options?: string[]; master?: keyof MasterData }[] }> = { home: { types: ["Task"], fields: [{ key: "controlledNumber", label: "Task number", required: true }, { key: "title", label: "Task title", required: true }, { key: "priority", label: "Priority", required: true, kind: "select", options: ["Low", "Normal", "High", "Critical"] }, { key: "dueDate", label: "Due date", kind: "date" }] }, rnd: { types: ["Project", "Part", "BOM", "Prototype", "Engineering change", "Design review"], fields: [{ key: "controlledNumber", label: "Project code", required: true }, { key: "title", label: "Project title", required: true }, { key: "category", label: "Type / category", required: true, kind: "select", options: ["New product", "Variant", "Research", "Sustaining engineering"] }, { key: "product", label: "Product", master: "products" }, { key: "owner", label: "Owner", master: "people" }, { key: "stage", label: "Stage", required: true, kind: "select", options: ["Concept", "Requirements", "Prototype", "Verification", "Released"] }, { key: "targetDate", label: "Target date", kind: "date" }, { key: "location", label: "Location", required: true, master: "locations" }] }, stores: { types: ["Purchase request", "Part", "Supplier", "RFQ", "Purchase order", "Receiving", "Stock movement"], fields: [{ key: "controlledNumber", label: "Purchase request number", required: true }, { key: "title", label: "Request title", required: true }, { key: "supplier", label: "Supplier", master: "suppliers" }, { key: "part", label: "Part", master: "parts" }, { key: "location", label: "Delivery location", required: true, master: "locations" }, { key: "dueDate", label: "Required date", kind: "date" }] }, production: { types: ["Production order", "Production test", "Release", "Dispatch"], fields: [{ key: "controlledNumber", label: "Production order number", required: true }, { key: "title", label: "Production order title", required: true }, { key: "route", label: "Production route", master: "routes" }, { key: "location", label: "Location", required: true, master: "locations" }, { key: "targetDate", label: "Planned completion", kind: "date" }] }, quality: { types: ["Inspection", "NCR", "CAPA", "Quality review"], fields: [{ key: "controlledNumber", label: "Inspection number", required: true }, { key: "title", label: "Inspection title", required: true }, { key: "location", label: "Location", required: true, master: "locations" }, { key: "targetDate", label: "Target closure", kind: "date" }] }, sales: { types: ["Enquiry", "Opportunity", "Order", "Handover"], fields: [{ key: "controlledNumber", label: "Enquiry number", required: true }, { key: "title", label: "Enquiry title", required: true }, { key: "customer", label: "Customer", master: "customers" }, { key: "targetDate", label: "Target date", kind: "date" }, { key: "location", label: "Location", required: true, master: "locations" }] }, people: { types: ["Person", "Training", "Leave", "Asset"], fields: [{ key: "controlledNumber", label: "Person number", required: true }, { key: "title", label: "Name", required: true }, { key: "location", label: "Location", required: true, master: "locations" }, { key: "dueDate", label: "Due date", kind: "date" }] } };
function RecordForm({ area, portal, onClose, onSave }: { area: AreaId; portal: PortalState; onClose: () => void; onSave: (record: Omit<RecordItem, "id" | "reference" | "createdAt" | "updatedAt">) => void }) { const spec = formSpecs[area]; const [type, setType] = useState(spec.types[0]); const [values, setValues] = useState<Record<string, string>>({}); const [error, setError] = useState(""); const field = (key: string) => values[key] ?? ""; const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const missing = spec.fields.find((item) => item.required && !field(item.key).trim()); if (missing) return setError(`${missing.label} is required.`); const invalid = spec.fields.find((item) => item.master && field(item.key) && !portal.masters[item.master].some((value) => value.toLowerCase() === field(item.key).toLowerCase())); if (invalid) return setError(`Select a managed ${invalid.label.toLowerCase()} option.`); onSave({ area, type, title: field("title").trim(), status: "Draft", priority: (field("priority") as Priority) || "Normal", notes: field("scope"), fields: values }); }; return <Modal title={`Create ${type}`} onClose={onClose} wide><form onSubmit={submit} className="space-y-5"><SelectField label="Record type" value={type} options={spec.types} onChange={setType}/><div className="grid gap-4 md:grid-cols-2">{spec.fields.map((item) => item.master ? <ManagedField key={item.key} item={item} value={field(item.key)} options={portal.masters[item.master]} onChange={(value) => setValues({ ...values, [item.key]: value })}/> : item.kind === "select" ? <SelectField key={item.key} label={`${item.label}${item.required ? " *" : ""}`} value={field(item.key)} options={["", ...(item.options ?? [])]} onChange={(value) => setValues({ ...values, [item.key]: value })}/> : <TextField key={item.key} label={item.label} type={item.kind === "date" ? "date" : "text"} required={item.required} value={field(item.key)} onChange={(value) => setValues({ ...values, [item.key]: value })}/>)}</div><label className="block text-sm font-medium">Requirements / scope<textarea value={field("scope")} onChange={(event) => setValues({ ...values, scope: event.target.value.slice(0, 2000) })} className="mt-1.5 min-h-28 w-full border border-input bg-background p-3 text-sm"/></label>{error && <p role="alert" className="text-sm text-danger">{error}</p>}<div className="flex justify-end gap-2"><Action onClick={onClose} label="Cancel"/><Action label={`Save ${type}`} primary submit/></div></form></Modal>; }
function ManagedField({ item, value, options, onChange }: { item: { label: string; required?: boolean }; value: string; options: string[]; onChange: (value: string) => void }) { return <label className="block text-sm font-medium">{item.label}{item.required ? " *" : ""}<input list={`options-${item.label}`} value={value} onChange={(event) => onChange(event.target.value)} placeholder={`Search ${item.label.toLowerCase()}`} className="mt-1.5 h-11 w-full border border-input bg-background px-3 text-sm"/><datalist id={`options-${item.label}`}>{options.map((option) => <option key={option} value={option}/>)}</datalist><span className="mt-1 block text-xs text-muted-foreground">Manage options in Administration.</span></label>; }

function AdminCommandCenter({ portal, activeDepartmentId, onClose, onUpdate, onLog, onContext }: { portal: PortalState; activeDepartmentId: string | null; onClose: () => void; onUpdate: (recipe: (state: PortalState) => PortalState) => void; onLog: (action: string, detail: string) => void; onContext: (id: string | null) => void }) { const [tab, setTab] = useState<"departments" | "roles" | "settings">("departments"); const [query, setQuery] = useState(""); const [density, setDensity] = useState<"comfortable" | "compact">("comfortable"); const [page, setPage] = useState(0); const [draft, setDraft] = useState({ name: "", code: "", type: departmentTypes[0], custom: "" }); const filtered = portal.departments.filter((department) => `${department.name} ${department.code} ${department.departmentType}`.toLowerCase().includes(query.toLowerCase())); const pageSize = density === "compact" ? 10 : 5; const current = filtered.slice(page * pageSize, page * pageSize + pageSize); const selected = portal.departments.find((department) => department.id === activeDepartmentId) ?? portal.departments[0]; const createDepartment = () => { const name = draft.name.trim(); const code = draft.code.trim().toUpperCase(); const type = draft.type === "Other/custom" ? draft.custom.trim() : draft.type; if (!name || !code || !type) return; if (portal.departments.some((department) => department.name.toLowerCase() === name.toLowerCase() || department.code === code)) return; const department: Department = { id: createId(), name, code, departmentType: type, customType: draft.type === "Other/custom" ? type : undefined, active: true, lead: "", sortOrder: portal.departments.length, settings: { ...blankSettings(), prefix: code } }; onUpdate((state) => ({ ...state, departments: [...state.departments, department] })); onLog("Department created", `${name} (${code}) configured by administrator`); setDraft({ name: "", code: "", type: departmentTypes[0], custom: "" }); }; return <Modal title="Administration command center" onClose={onClose} wide><div className="mb-5 flex flex-wrap gap-2 border-b border-border pb-4">{(["departments", "roles", "settings"] as const).map((item) => <button key={item} onClick={() => setTab(item)} className={`h-9 px-3 text-sm font-semibold capitalize ${tab === item ? "bg-primary text-primary-foreground" : "border border-border"}`}>{item === "settings" ? "Department settings" : item}</button>)}<span className="ml-auto font-mono text-[10px] uppercase text-muted-foreground">Acting role · Administrator</span></div>{tab === "departments" ? <><div className="grid gap-3 border border-border bg-panel p-4 md:grid-cols-4"><TextField label="Department name" value={draft.name} onChange={(name) => setDraft({ ...draft, name })}/><TextField label="Code" value={draft.code} onChange={(code) => setDraft({ ...draft, code })}/><SelectField label="Department type" value={draft.type} options={departmentTypes} onChange={(type) => setDraft({ ...draft, type })}/>{draft.type === "Other/custom" ? <TextField label="Custom type" value={draft.custom} onChange={(custom) => setDraft({ ...draft, custom })}/> : <Action label="Create department" onClick={createDepartment} primary/>}</div>{draft.type === "Other/custom" && <div className="mt-3"><Action label="Create department" onClick={createDepartment} primary/></div>}<div className="mt-5 flex flex-wrap gap-2"><input aria-label="Filter departments" value={query} onChange={(event) => { setQuery(event.target.value); setPage(0); }} placeholder="Filter departments" className="h-10 min-w-52 flex-1 border border-input bg-background px-3 text-sm"/><SelectField label="Row density" value={density} options={["comfortable", "compact"]} onChange={(value) => setDensity(value as "comfortable" | "compact")}/></div><div className="mt-3 overflow-x-auto border border-border"><table className="w-full min-w-[42rem] text-left text-sm"><thead className="bg-panel font-mono text-[10px] uppercase text-muted-foreground"><tr><th className="p-3">Department</th><th className="p-3">Type</th><th className="p-3">Lead</th><th className="p-3">Status</th><th className="p-3">Actions</th></tr></thead><tbody>{current.map((department) => <tr key={department.id} className="border-t border-border"><td className={`p-3 ${density === "compact" ? "py-2" : "py-4"}`}><strong>{department.name}</strong><small className="ml-2 font-mono text-muted-foreground">{department.code}</small></td><td className="p-3">{department.departmentType}</td><td className="p-3">{department.lead || "No lead assigned"}</td><td className="p-3">{department.active ? "Active" : "Inactive"}</td><td className="p-3"><button onClick={() => onContext(department.id)} className="font-semibold text-steel">Manage</button><button onClick={() => { onUpdate((state) => ({ ...state, departments: state.departments.map((item) => item.id === department.id ? { ...item, active: !item.active } : item) })); onLog("Department status changed", `${department.name} ${department.active ? "deactivated" : "activated"}`); }} className="ml-3 font-semibold text-danger">{department.active ? "Deactivate" : "Activate"}</button></td></tr>)}</tbody></table>{!current.length && <p className="p-8 text-center text-sm text-muted-foreground">No departments match the current filters.</p>}</div><div className="mt-3 flex items-center justify-between text-sm"><span>{filtered.length} department{filtered.length === 1 ? "" : "s"}</span><div className="flex gap-2"><Action label="Previous" onClick={() => setPage(Math.max(0, page - 1))}/><Action label="Next" onClick={() => setPage((page + 1) * pageSize < filtered.length ? page + 1 : page)}/></div></div></> : tab === "roles" ? <RoleManager portal={portal} onUpdate={onUpdate} onLog={onLog}/> : <DepartmentSettingsManager department={selected} onUpdate={onUpdate} onLog={onLog}/>}</Modal>; }
function RoleManager({ portal, onUpdate, onLog }: { portal: PortalState; onUpdate: (recipe: (state: PortalState) => PortalState) => void; onLog: (action: string, detail: string) => void }) { const [name, setName] = useState(""); const [departmentId, setDepartmentId] = useState(""); const [permissions, setPermissions] = useState<string[]>(["records:view"]); const create = () => { const department = portal.departments.find((item) => item.id === departmentId); if (!department || !name.trim()) return; const role = { id: createId(), departmentId, name: name.trim(), permissions, active: true }; onUpdate((state) => ({ ...state, roles: [...state.roles, role] })); onLog("Department role created", `${role.name} created for ${department.name}`); setName(""); setPermissions(["records:view"]); }; return <div><p className="text-sm leading-6 text-muted-foreground">Sub-roles scope access by department. Assignments remain blank until a confirmed team member is added; this never impersonates another account.</p><div className="mt-4 grid gap-3 border border-border bg-panel p-4 md:grid-cols-3"><TextField label="Role name" value={name} onChange={setName}/><SelectField label="Department" value={departmentId} options={["", ...portal.departments.filter((item) => item.active).map((item) => item.name)]} onChange={(value) => setDepartmentId(portal.departments.find((item) => item.name === value)?.id ?? "")}/><Action label="Create role" onClick={create} primary/></div><div className="mt-4 grid gap-2 sm:grid-cols-2">{permissionOptions.map((permission) => <label key={permission} className="flex items-center gap-2 border border-border p-3 text-sm"><input type="checkbox" checked={permissions.includes(permission)} onChange={(event) => setPermissions(event.target.checked ? [...permissions, permission] : permissions.filter((item) => item !== permission))}/>{permission}</label>)}</div><div className="mt-5 space-y-2">{portal.roles.length ? portal.roles.map((role) => <div key={role.id} className="flex flex-wrap items-center justify-between gap-2 border-b border-border py-3"><span><strong>{role.name}</strong><small className="ml-2 text-muted-foreground">{portal.departments.find((department) => department.id === role.departmentId)?.name ?? "Unknown department"}</small></span><span className="font-mono text-[10px] text-muted-foreground">{role.permissions.length} permissions</span></div>) : <p className="text-sm text-muted-foreground">No department sub-roles configured.</p>}</div></div>; }
function DepartmentSettingsManager({ department, onUpdate, onLog }: { department: Department | undefined; onUpdate: (recipe: (state: PortalState) => PortalState) => void; onLog: (action: string, detail: string) => void }) { const [group, setGroup] = useState<keyof Pick<DepartmentSettings, "activityTypes" | "templates" | "approvalGates" | "milestones" | "kpis" | "notifications">>("activityTypes"); const [value, setValue] = useState(""); if (!department) return <p className="py-8 text-center text-sm text-muted-foreground">Create a department to configure its calendar, numbering, gates and KPI options.</p>; const add = () => { const next = value.trim(); if (!next) return; onUpdate((state) => ({ ...state, departments: state.departments.map((item) => item.id === department.id ? { ...item, settings: { ...item.settings, [group]: [...item.settings[group], next] } } : item) })); onLog("Department setting added", `${next} added to ${department.name}`); setValue(""); }; return <div><p className="mb-4 text-sm text-muted-foreground">Managing {department.name}. These controls define local activity options and controlled numbering.</p><div className="grid gap-3 border border-border bg-panel p-4 md:grid-cols-3"><SelectField label="Setting group" value={group} options={["activityTypes", "templates", "approvalGates", "milestones", "kpis", "notifications"]} onChange={(value) => setGroup(value as typeof group)}/><TextField label="New option" value={value} onChange={setValue}/><Action label="Add option" onClick={add} primary/></div><div className="mt-4 grid gap-4 md:grid-cols-3"><TextField label="Number prefix" value={department.settings.prefix} onChange={(prefix) => onUpdate((state) => ({ ...state, departments: state.departments.map((item) => item.id === department.id ? { ...item, settings: { ...item.settings, prefix } } : item) }))}/><TextField label="Number format" value={department.settings.format} onChange={(format) => onUpdate((state) => ({ ...state, departments: state.departments.map((item) => item.id === department.id ? { ...item, settings: { ...item.settings, format } } : item) }))}/><div className="border border-border bg-card p-3"><p className="font-mono text-[10px] uppercase text-muted-foreground">Preview</p><p className="mt-2 font-semibold">{department.settings.format.replace("{PREFIX}", department.settings.prefix || department.code).replace("{YYYY}", String(new Date().getFullYear())).replace("{####}", String(department.settings.sequence).padStart(4, "0"))}</p></div></div><div className="mt-4 flex flex-wrap gap-2">{department.settings[group].map((item) => <span key={item} className="border border-border bg-panel px-2 py-1 text-xs">{item}</span>)}</div></div>; }

function Wizard({ portal, onClose, onSave }: { portal: PortalState; onClose: () => void; onSave: (next: PortalState) => void }) { const [step, setStep] = useState(portal.setupStep); const [setup, setSetup] = useState(portal.setup); const save = () => onSave({ ...portal, setup, setupStep: step }); return <Modal title={setupSteps[step]} onClose={onClose} wide><p className="font-mono text-[10px] uppercase text-muted-foreground">Step {step + 1} of 10</p><div className="mt-3 h-2 bg-panel-strong"><div className="h-full bg-steel" style={{ width: `${(step + 1) * 10}%` }}/></div><div className="mt-5 grid gap-5 md:grid-cols-[13rem_1fr]"><div className="grid grid-cols-2 gap-1 md:block">{setupSteps.map((name, index) => <button key={name} onClick={() => { save(); setStep(index); }} className={`w-full p-2 text-left text-xs ${index === step ? "bg-accent" : "text-muted-foreground"}`}>{index + 1}. {name}</button>)}</div><div className="space-y-4">{step === 0 ? <><TextField label="Company name" value={setup.company} onChange={(company) => setSetup({ ...setup, company })} required/><TextField label="Main location" value={setup.location} onChange={(location) => setSetup({ ...setup, location })} required/><SelectField label="Working days" value={setup.workingDays} options={["Monday – Friday", "Monday – Saturday", "Monday – Sunday", "Custom schedule"]} onChange={(workingDays) => setSetup({ ...setup, workingDays })}/><SelectField label="Time zone" value={setup.timezone} options={["Asia/Kolkata", "UTC"]} onChange={(timezone) => setSetup({ ...setup, timezone })}/></> : <div className="border border-dashed border-border bg-panel p-4"><p className="font-semibold">Configuration ready when confirmed</p><p className="mt-2 text-sm leading-6 text-muted-foreground">Use Administration to add only confirmed departments, roles, gates, master options and escalation rules. No operational data has been added for you.</p></div>}</div></div><div className="mt-6 flex justify-between border-t border-border pt-4"><Action label="Back" onClick={() => { save(); setStep(Math.max(0, step - 1)); }}/><div className="flex gap-2"><Action label="Save & resume" onClick={() => { save(); onClose(); }}/><Action label={step === 9 ? "Save checklist" : "Next step"} onClick={() => { const next = Math.min(9, step + 1); onSave({ ...portal, setup, setupStep: next }); if (step === 9) onClose(); else setStep(next); }} primary/></div></div></Modal>; }
function SearchPanel({ records, onClose, onSelect }: { records: RecordItem[]; onClose: () => void; onSelect: (record: RecordItem) => void }) { const [query, setQuery] = useState(""); const results = useMemo(() => records.filter((record) => `${record.reference} ${record.title} ${record.type}`.toLowerCase().includes(query.toLowerCase())), [records, query]); return <Modal title="Search portal records" onClose={onClose}><input autoFocus value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search records by name or reference" className="h-11 w-full border border-input bg-background px-3 text-sm"/><div className="mt-4">{results.length ? results.map((record) => <button key={record.id} onClick={() => onSelect(record)} className="flex w-full items-center justify-between border-b border-border py-3 text-left"><span><strong className="block text-sm">{record.title}</strong><small className="font-mono text-muted-foreground">{record.reference} · {areaById(record.area).short}</small></span><ChevronRight className="size-4"/></button>) : <p className="py-8 text-center text-sm text-muted-foreground">No matching records yet.</p>}</div></Modal>; }
function HistoryPanel({ audit, onClose }: { audit: AuditEvent[]; onClose: () => void }) { return <Modal title="History" onClose={onClose}>{audit.length ? audit.map((event) => <div key={event.id} className="border-b border-border py-3"><p className="font-semibold">{event.action}</p><p className="mt-1 text-sm text-muted-foreground">{event.detail}</p><p className="mt-1 font-mono text-[10px] text-muted-foreground">{event.at}</p></div>) : <p className="py-8 text-center text-sm text-muted-foreground">No delegated or administrative actions recorded yet.</p>}</Modal>; }
function ApprovalsPanel({ approvals, onClose }: { approvals: PortalState["approvals"]; onClose: () => void }) { return <Modal title="Human approvals" onClose={onClose}><p className="mb-4 text-sm text-muted-foreground">Automation cannot approve controlled operations.</p>{approvals.length ? approvals.map((approval) => <p key={approval.id} className="border-b border-border py-3">{approval.title}</p>) : <p className="py-8 text-center text-sm text-muted-foreground">No approvals are awaiting a human decision.</p>}</Modal>; }
function DocumentsPanel({ documents, onClose }: { documents: PortalState["documents"]; onClose: () => void }) { return <Modal title="Document references" onClose={onClose}>{documents.length ? documents.map((document) => <a key={document.id} className="block border-b border-border py-3" href={document.url}><strong>{document.title}</strong></a>) : <p className="py-8 text-center text-sm text-muted-foreground">No document references yet.</p>}</Modal>; }

function PageHeader({ eyebrow, title, description, actions }: { eyebrow: string; title: string; description: string; actions: ReactNode }) { return <div className="mb-6 flex flex-wrap items-end justify-between gap-4"><div><p className="font-mono text-[10px] uppercase tracking-[.16em] text-moss">{eyebrow}</p><h1 className="mt-2 text-3xl font-semibold md:text-4xl">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">{description}</p></div><div className="flex gap-2">{actions}</div></div>; }
function Modal({ title, onClose, children, wide }: { title: string; onClose: () => void; children: ReactNode; wide?: boolean }) { return <div className="fixed inset-0 z-50 grid place-items-end bg-ink/35 md:place-items-center md:p-6"><section role="dialog" aria-modal="true" aria-label={title} className={`max-h-[92vh] w-full overflow-auto bg-popover shadow-2xl ${wide ? "max-w-5xl" : "max-w-xl"}`}><header className="sticky top-0 flex items-center justify-between border-b border-border bg-popover px-5 py-4"><h2 className="text-lg font-semibold">{title}</h2><button aria-label="Close" onClick={onClose} className="grid size-9 place-items-center bg-secondary"><X className="size-4"/></button></header><div className="p-5">{children}</div></section></div>; }
function TextField({ label, value, onChange, required, type = "text" }: { label: string; value: string; onChange: (value: string) => void; required?: boolean; type?: string }) { return <label className="block text-sm font-medium">{label}{required ? " *" : ""}<input type={type} required={required} value={value} onChange={(event) => onChange(event.target.value)} className="mt-1.5 h-11 w-full border border-input bg-background px-3 text-sm"/></label>; }
function SelectField({ label, value, options, onChange }: { label: string; value: string; options: string[]; onChange: (value: string) => void }) { return <label className="block text-sm font-medium">{label}<select value={value} onChange={(event) => onChange(event.target.value)} className="mt-1.5 h-11 w-full border border-input bg-background px-3 text-sm">{options.map((option) => <option key={option} value={option}>{option || "Select an option"}</option>)}</select></label>; }
function Action({ label, onClick, primary, submit }: { label: string; onClick?: () => void; primary?: boolean; submit?: boolean }) { return <button type={submit ? "submit" : "button"} onClick={onClick} className={`inline-flex h-10 items-center justify-center whitespace-nowrap px-3 text-sm font-semibold ${primary ? "bg-primary text-primary-foreground" : "border border-border bg-card"}`}>{label}</button>; }
function Metric({ label, value, detail, tone }: { label: string; value: string; detail: string; tone: "danger" | "steel" | "moss" | "warning" }) { const color = tone === "danger" ? "bg-danger" : tone === "steel" ? "bg-steel" : tone === "moss" ? "bg-moss" : "bg-warning"; return <div className="border border-border bg-card p-4"><div className="flex justify-between"><p className="font-mono text-[10px] uppercase tracking-[.12em] text-muted-foreground">{label}</p><span className={`size-2 ${color}`}/></div><p className="mt-3 text-3xl font-semibold">{value}</p><p className="mt-1 text-xs text-muted-foreground">{detail}</p></div>; }
function Status({ status }: { status: RecordStatus }) { const tone = status === "Approved" || status === "Released" ? "bg-accent text-accent-foreground" : status === "Archived" ? "bg-secondary" : "bg-panel-strong"; return <span className={`inline-flex px-2 py-1 font-mono text-[10px] uppercase ${tone}`}>{status}</span>; }
function Empty({ onCreate, label }: { onCreate: () => void; label: string }) { return <div className="grid place-items-center p-12 text-center"><ClipboardCheck className="size-6 text-muted-foreground"/><h2 className="mt-3 font-semibold">No records yet</h2><p className="mt-2 max-w-sm text-sm leading-6 text-muted-foreground">No sample activity has been created. Add the first confirmed record when ready.</p><div className="mt-4"><Action onClick={onCreate} label={label} primary/></div></div>; }
function HeaderAction({ label, icon: Icon, onClick }: { label: string; icon: typeof Bell; onClick: () => void }) { return <button aria-label={label} onClick={onClick} className="grid size-10 place-items-center border border-border bg-panel"><Icon className="size-4"/></button>; }
function Brand() { return <div className="flex items-center gap-3"><div className="grid size-9 place-items-center bg-sidebar-primary font-mono text-[11px] text-sidebar-primary-foreground">SS</div><div><p className="text-sm font-semibold">Six Sense Mobility</p><p className="font-mono text-[10px] uppercase text-muted-foreground">Operations portal</p></div></div>; }
function AreaNav({ area, active, onClick }: { area: typeof areas[number]; active: boolean; onClick: () => void }) { const Icon = area.icon; return <button onClick={onClick} className={`flex w-full items-center gap-3 px-3 py-2.5 text-left text-sm ${active ? "bg-sidebar-primary text-sidebar-primary-foreground" : "text-sidebar-foreground"}`}><Icon className="size-4"/>{area.name}</button>; }
function MobileMenu({ onClose, onNavigate }: { onClose: () => void; onNavigate: (area: AreaId) => void }) { return <div className="fixed inset-0 z-50 bg-ink/30 lg:hidden"><div className="h-full w-[min(19rem,88vw)] bg-sidebar p-4"><div className="flex items-center justify-between"><Brand/><button aria-label="Close menu" onClick={onClose}><X className="size-5"/></button></div><nav className="mt-8 space-y-1">{areas.map((area) => <AreaNav key={area.id} area={area} active={false} onClick={() => { onNavigate(area.id); onClose(); }}/>)}</nav></div></div>; }